CREATE TABLE IF NOT EXISTS duty_categories (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(200) NOT NULL UNIQUE,
    description TEXT NOT NULL DEFAULT '',
    icon VARCHAR(500) NOT NULL DEFAULT '',
    sort_order INTEGER NOT NULL DEFAULT 0,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS duties (
    id BIGSERIAL PRIMARY KEY,
    category_id BIGINT NOT NULL REFERENCES duty_categories(id) ON DELETE RESTRICT,
    name VARCHAR(300) NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    sort_order INTEGER NOT NULL DEFAULT 0,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(category_id,name)
);

CREATE TABLE IF NOT EXISTS vacancy_duties (
    id BIGSERIAL PRIMARY KEY,
    vacancy_id BIGINT NOT NULL REFERENCES vacancies(id) ON DELETE CASCADE,
    duty_id BIGINT NOT NULL REFERENCES duties(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(vacancy_id,duty_id)
);

CREATE TABLE IF NOT EXISTS resume_duties (
    id BIGSERIAL PRIMARY KEY,
    resume_id BIGINT NOT NULL REFERENCES resumes(id) ON DELETE CASCADE,
    duty_id BIGINT NOT NULL REFERENCES duties(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(resume_id,duty_id)
);

CREATE INDEX IF NOT EXISTS duty_categories_sort_idx ON duty_categories(is_active,sort_order,id);
CREATE INDEX IF NOT EXISTS duties_category_sort_idx ON duties(category_id,is_active,sort_order,id);
CREATE INDEX IF NOT EXISTS duties_name_search_idx ON duties(LOWER(name));
CREATE INDEX IF NOT EXISTS vacancy_duties_duty_idx ON vacancy_duties(duty_id,vacancy_id);
CREATE INDEX IF NOT EXISTS resume_duties_duty_idx ON resume_duties(duty_id,resume_id);

